select coalesce(jsonb_agg(t.failed),'[]'::jsonb)as failures from (select 'inventory:inv_c38576419bf3e137d53bbde2afa6ce14' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_c38576419bf3e137d53bbde2afa6ce14' and payload#>'{description}'=$verify_710aa5ba9966d542$"Objeto · Precio base · Peso\nRopas comunes · 5 pp · 3 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_710aa5ba9966d542$::jsonb and payload#>'{rules,definition,description}'=$verify_8b249a8c7a296f12$[{"id":"official-table","rows":[["Ropas comunes","5 pp","3 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_8b249a8c7a296f12$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_d1ca6d36842a5fc238786b8c34c18314' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_d1ca6d36842a5fc238786b8c34c18314' and payload#>'{description}'=$verify_12449d2dc03ff23a$"Carta con una pregunta pendiente."$verify_12449d2dc03ff23a$::jsonb and payload#>'{features}'=$verify_bffc6f31a0ed827b$[{"id":"preserved-personal-rule","kind":"other","name":"Reglas de la variante personal","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"","showInActions":false}]$verify_bffc6f31a0ed827b$::jsonb and payload#>'{rules,definition,description}'=$verify_e284c9d5603cebf4$[{"id":"player-description","section":"description","type":"paragraph","provenance":"campaign","sourceIds":["ece-current-copy"],"text":"Carta con una pregunta pendiente."}]$verify_e284c9d5603cebf4$::jsonb and payload#>'{catalog,revision}'=$verify_6b86b273ff34fce1$1$verify_6b86b273ff34fce1$::jsonb and revision=2) union all select 'inventory:inv_e98fd6e34e2296c8978e80e600459787' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_e98fd6e34e2296c8978e80e600459787' and payload#>'{description}'=$verify_351feef9fb69f361$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nVirote de ballesta · 1 po · 1.5 lb · 20 · 0.075 · 5\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_351feef9fb69f361$::jsonb and payload#>'{rules,definition,description}'=$verify_6e4d033d011196fd$[{"id":"official-table","rows":[["Virote de ballesta","1 po","1.5 lb","20","0.075","5"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_6e4d033d011196fd$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_ebb896618eca067fb9bbe3dab7a2d60d' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_b935626903ae074cc0314a11a812f47b' and entity_id='inv_ebb896618eca067fb9bbe3dab7a2d60d' and payload#>'{features}'=$verify_f90f6a78613d875c$[{"id":"official-2014-rule","kind":"other","name":"Reglas de la variante","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando impactes a un infernal o muerto viviente con esta arma mágica, esa criatura recibirá 2d6 de daño radiante adicional. Si al objetivo le quedan 25 puntos de golpe o menos tras sufrir este daño, deberá superar una tirada de salvación de Sabiduría con CD 15 o será destruido. Si la supera, la criatura quedará asustada de ti hasta el final de tu siguiente turno.\n\nMientras empuñes esta arma, emitirá luz brillante en un radio de 6 m y luz tenue 6 m más allá.\n\nResolver las condiciones, objetivos y efectos descritos en la mesa. No concede automáticamente todas las opciones de una familia ni conjuros a la lista de clase.\n\nDuración: Según la regla oficial..\n\nConcentración: según el conjuro.","showInActions":false}]$verify_f90f6a78613d875c$::jsonb and payload#>'{rules,personalDescription}'=$verify_d26e14df57c76560$"Cuando golpeas a un Demonio o a un No Muerto con esta arma mágica, esa criatura recibe 2d6 puntos de daño Radiante adicionales. Si el objetivo tiene 25 Puntos de Golpe o menos después de recibir este daño, debe superar una tirada de salvación de Sabiduría CD 15 o será destruido. Si la tirada de salvación tiene éxito, la criatura tiene el estado de Asustado hasta el final de tu siguiente turno.\n\nLuz. Mientras sostienes esta arma, emite Luz brillante en un radio de 20 pies y Luz tenue en otros 20 pies. La competencia con una maza te permite sumar tu bonificación por competencia a la tirada de ataque de cualquier ataque que realices con ella."$verify_d26e14df57c76560$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_058c8377210e8115cf71478a1d2b8199' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_058c8377210e8115cf71478a1d2b8199' and payload#>'{features}'=$verify_9ad7b9db04c41b3a$[{"id":"mundane-rule","kind":"other","name":"Uso del equipo","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Útiles para disfrazarse. Esta bolsa con productos de maquillaje, tinte para el pelo y pequeños accesorios te ayuda a disfrazarte y cambiar así tu apariencia. La competencia con estos útiles te permite sumar tu bonificador por competencia a las pruebas de característica para crear un disfraz que engañe a la vista.\n\nResolver las reglas descritas y sus condiciones en la mesa.\n\nDuración: Según la regla..","showInActions":false}]$verify_9ad7b9db04c41b3a$::jsonb and revision=2) union all select 'inventory:inv_2c2807551bd79648d79183dd28857f46' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_2c2807551bd79648d79183dd28857f46' and payload#>'{features}'=$verify_8f83b90bcdfccf65$[{"id":"mundane-assisted-use","kind":"other","name":"Contenido del paquete","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Paquete de ladrón (16 po). Incluye una mochila, una bolsa con 1000 bolas de metal, 3 m de cordel, una campana, 5 velas, una palanqueta, un martillo, 10 pitones, una linterna sorda, 2 frascos de aceite, raciones para 5 días, un yesquero y una cantimplora. Además, el paquete tiene una cuerda de cáñamo de 15 m enganchada en un lado.\n\nDuración: Según su uso..","showInActions":false}]$verify_8f83b90bcdfccf65$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_75839275c094535772a5c065a209240b' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_75839275c094535772a5c065a209240b' and payload#>'{description}'=$verify_558a95cebcb036e3$"Objeto · Precio base · Peso · Unidades por paquete · Peso por unidad (lb) · Precio por unidad (pc)\nFlecha · 1 po · 1 lb · 20 · 0.05 · 5\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_558a95cebcb036e3$::jsonb and payload#>'{rules,definition,description}'=$verify_1086a208ec8f4634$[{"id":"official-table","rows":[["Flecha","1 po","1 lb","20","0.05","5"]],"type":"table","columns":["Objeto","Precio base","Peso","Unidades por paquete","Peso por unidad (lb)","Precio por unidad (pc)"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_1086a208ec8f4634$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_82f14c91203dcc025daebf305240e124' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_82f14c91203dcc025daebf305240e124' and payload#>'{description}'=$verify_7d0ad9435aca71d9$"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea."$verify_7d0ad9435aca71d9$::jsonb and payload#>'{rules,definition,description}'=$verify_858a5902d36eada8$[{"id":"original-text-0","text":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.","type":"paragraph","section":"description","sourceIds":["original:cb6ee5a619b222ffe82fbe5dc106180a8e11292b94d8b51402f4983dc92a0803"],"provenance":"unreviewed"}]$verify_858a5902d36eada8$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=1) union all select 'inventory:inv_89ccdfb2bf0a21fb6c618529141cb18b' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_89ccdfb2bf0a21fb6c618529141cb18b' and payload#>'{description}'=$verify_1b9f73811a287e94$"Objeto · Precio base · Peso\nRopas de calidad · 15 po · 6 lb\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_1b9f73811a287e94$::jsonb and payload#>'{rules,definition,description}'=$verify_44789f9e192f265d$[{"id":"official-table","rows":[["Ropas de calidad","15 po","6 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"}]$verify_44789f9e192f265d$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=2) union all select 'inventory:inv_997af72fbd24fc95193796e4d131b5e3' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_997af72fbd24fc95193796e4d131b5e3' and payload#>'{features}'=$verify_5c3ba9d5bc2ed536$[{"id":"mundane-rule","kind":"other","name":"Uso del equipo","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Herramientas de ladrón. Este conjunto de herramientas incluye una lima pequeña, un juego de ganzúas, un espejito con un asa metálica, una serie de tijeras de punta estrecha y unas tenazas. Si tienes competencia con estas herramientas, podrás sumar tu bonificador por competencia a las pruebas de característica para desarmar trampas o forzar cerraduras.\n\nResolver las reglas descritas y sus condiciones en la mesa.\n\nDuración: Según la regla..","showInActions":false}]$verify_5c3ba9d5bc2ed536$::jsonb and revision=2) union all select 'inventory:inv_ab29f134c3a433df9f3748bb0f74ffbd' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_ab29f134c3a433df9f3748bb0f74ffbd' and payload#>'{description}'=$verify_f7f023db0ab2a01d$"Objeto · Precio base · Peso\nAljaba · 1 po · 1 lb\n\nAljaba. Una aljaba puede contener hasta 20 flechas.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_f7f023db0ab2a01d$::jsonb and payload#>'{features}'=$verify_ad95de5033aa8476$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Aljaba. Una aljaba puede contener hasta 20 flechas.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_ad95de5033aa8476$::jsonb and payload#>'{rules,definition,description}'=$verify_2553e910a16c7cd4$[{"id":"official-table","rows":[["Aljaba","1 po","1 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Aljaba. Una aljaba puede contener hasta 20 flechas.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_2553e910a16c7cd4$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=3) union all select 'inventory:inv_df0f0d60fa767a43d423847b8e2e9872' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_df0f0d60fa767a43d423847b8e2e9872' and payload#>'{features}'=$verify_ae23ed56aa8fbde8$[{"id":"official-use","kind":"passive","name":"Propiedades oficiales","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Mientras calces estas botas, tus pasos no harán ruido, independientemente de la superficie que pises. También tendrás ventaja en las pruebas de Destreza (Sigilo) que requieran moverse sin hacer ruido.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_ae23ed56aa8fbde8$::jsonb and payload#>'{catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and revision=1) union all select 'inventory:inv_f0437da48a839a9472a94e2e679a9f94' as failed where not exists(select 1 from public.campaign_state_fragments where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and fragment_kind='character-inventory' and parent_id='chr_c0d4a321021830d8dc5e7313710d762a' and entity_id='inv_f0437da48a839a9472a94e2e679a9f94' and payload#>'{features}'=$verify_628909b16073e6e5$[{"id":"itf_27c79e0ad8db3a51e69d6511e43b8c52","kind":"action","name":"Hoja Fásica","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Hoja Fásica","expression":"1d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Cuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.","showInActions":true},{"id":"phase-blade","kind":"other","name":"Hoja Fásica · Stix","uses":null,"order":1,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"1d6"}],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false},{"id":"shadow-step","kind":"bonus-action","name":"Salto entre Sombras","uses":null,"order":2,"rolls":[],"active":false,"bonuses":[],"chargeCost":1,"toggleable":false,"description":"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea.\n\nHoja Fásica\nCuando Stix realiza un ataque con la daga y obtiene un 20 natural, puede hacer que la hoja atraviese parcialmente el cuerpo del objetivo antes de volver a su estado normal.\nEl ataque inflige 1d6 de daño de fuerza adicional.\n\nHoja Fásica El ataque inflige 1d6 de daño de fuerza adicional. Salto entre Sombras Una vez por descanso corto o largo, Stix puede utilizar una acción adicional para hacer que la daga y su portador entren brevemente en fase. Stix se teletransporta hasta 15 pies hacia un espacio desocupado que pueda ver. Durante este desplazamiento no provoca ataques de oportunidad.\n\nTeletransporte hasta 15 pies a espacio desocupado visible, sin ataques de oportunidad; una vez por descanso corto o largo.\n\nDuración: Instantánea.\n\nAlcance: 15 pies.\n\nCoste: 1 salto.","showInActions":true}]$verify_628909b16073e6e5$::jsonb and payload#>'{rules,personalDescription}'=$verify_7d0ad9435aca71d9$"A primera vista parece una daga extraordinariamente bien fabricada, aunque no particularmente extravagante. La hoja, estrecha y perfectamente equilibrada, está hecha sobre una pieza de acero de la Forja Vann Durel, reconocible por la diminuta marca del yunque vivo grabada cerca de la guarda.\nSin embargo, la empuñadura revela que alguien ha intervenido posteriormente sobre el trabajo original.\n\nA ambos lados de la base de la hoja se encuentran incrustados dos pequeños colmillos de araña de fase, tratados y pulidos hasta adquirir una apariencia semejante al marfil oscuro. Sathrek ha utilizado sus propiedades naturales como conductores de energía planar, integrándolos en la estructura de la daga mediante finísimos filamentos metálicos.\nLa guarda es de plata ennegrecida y presenta pequeñas inscripciones arcanas prácticamente invisibles a simple vista. El pomo contiene una diminuta cavidad destinada a albergar una pequeña cantidad de cristal luciente, aunque no necesita un cristal para funcionar.\nLa daga no parece haber sido fabricada para exhibirse.\nEstá hecha para desaparecer.\nCuando se mueve rápidamente, durante una fracción de segundo la hoja parece perder definición, como si estuviera ligeramente fuera de fase con el mundo que la rodea."$verify_7d0ad9435aca71d9$::jsonb and payload#>'{catalog,revision}'=$verify_b17ef6d19c7a5b1e$16$verify_b17ef6d19c7a5b1e$::jsonb and revision=2) union all select 'merchant:imported:monster:legacy:1f706ea5cb33f5940fe687b5' as failed where not exists(select 1 from public.campaign_content_entries where campaign_id='9e5f3b10-be82-456c-9e9a-c2ec4a6b97cd' and kind='monster' and content_key='imported:monster:legacy:1f706ea5cb33f5940fe687b5' and payload#>'{inventory,0,description}'=$verify_383ecff6579ff2c0$"Objeto · Precio base · Peso\nAbrojos (bolsa de 20) · 1 po · 2 lb\n\nAbrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_383ecff6579ff2c0$::jsonb and payload#>'{inventory,0,features}'=$verify_816adba2fd0e635e$[{"id":"mundane-use","kind":"other","name":"Uso del objeto","uses":null,"order":0,"rolls":[],"active":false,"bonuses":[],"chargeCost":0,"toggleable":false,"description":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.\n\nDuración: Mientras se cumplen los requisitos..","showInActions":false}]$verify_816adba2fd0e635e$::jsonb and payload#>'{inventory,0,rules,definition,description}'=$verify_ad9e1c5eb1c88758$[{"id":"official-table","rows":[["Abrojos (bolsa de 20)","1 po","2 lb"]],"type":"table","columns":["Objeto","Precio base","Peso"],"section":"description","sourceIds":["srd-5.1-en-equipment"],"provenance":"reviewed-translation"},{"id":"official-rules-0","text":"Abrojos. Puedes usar tu acción para esparcir una bolsa de abrojos sobre una superficie cuadrada de 1,5 m de lado. Todas las criaturas que entren en la zona deberán superar una tirada de salvación de Destreza con CD 15 o no podrán moverse más ese turno y sufrirán 1 de daño perforante. Al sufrir este daño, la velocidad caminando de la criatura se reduce en 3 m hasta que recupere al menos 1 punto de golpe. Sin embargo, si una criatura se desplaza por la zona a la mitad de su velocidad, no tendrá que hacer la tirada de salvación.","type":"paragraph","section":"rules","sourceIds":["srd-5.1-es-equipment"],"provenance":"official-spanish"}]$verify_ad9e1c5eb1c88758$::jsonb and payload#>'{inventory,0,catalog,revision}'=$verify_4e07408562bedb8b$3$verify_4e07408562bedb8b$::jsonb and payload#>'{inventory,1,description}'=$verify_b941c3ef7d1ae2c4$"Objeto · Precio base · Peso · Daño base · Propiedades · Bonificación mágica\nAlabarda feroz · 20 po (solo objeto mundano base; no es el precio de la variante mágica) · 6 lb · 1d10 cortante · Pesada, Gran alcance, A dos manos · +0\n\nCuando sacas un 20 en la tirada de ataque con esta arma mágica, el objetivo recibe 7 puntos de daño adicional del tipo de daño del arma.\n\nEsta obra incluye materiales extraídos del Documento de referencia del sistema 5.1 (‘SRD 5.1’) de Wizards of the Coast LLC, que está disponible en https://dnd.wizards.com/es/resources/systems-reference-document. El SRD 5.1 tiene la licencia Creative Commons Atribución/Reconocimiento 4.0 Licencia Pública Internacional, que está disponible en https://creativecommons.org/licenses/by/4.0/legalcode.es."$verify_b941c3ef7d1ae2c4$::jsonb and payload#>'{inventory,1,features}'=$verify_4543b46f281f3b43$[{"id":"vicious-natural-20","kind":"other","name":"Daño adicional con un 20 natural","uses":null,"order":0,"rolls":[{"mode":"normal","label":"Daño condicionado","expression":"7"}],"active":false,"bonuses":[],"chargeCost":0,